package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.time.StopWatch#stop()
 */
public class StopWatch_stop_TriageGen1Test {

    @Test
    public void testStop_WhenRunning_ShouldStopSuccessfully() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();

        // Verify state before stop
        assertTrue("StopWatch should be running", stopWatch.isRunning());

        stopWatch.stop();

        // Verify state after stop
        assertFalse("StopWatch should not be running after stop()", stopWatch.isRunning());
        // Verify time is recorded (greater than 0 if some time passed, but at least not default 0 if started)
        assertTrue("Time should be recorded", stopWatch.getTime() >= 0);
    }

    @Test
    public void testStop_WhenSuspended_ShouldStopSuccessfully() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.suspend();

        // Verify suspended state
        assertTrue("StopWatch should be suspended", stopWatch.isSuspended());

        stopWatch.stop();

        // Verify state after stop
        assertFalse("StopWatch should not be running after stop()", stopWatch.isRunning());
    }

    @Test(expected = IllegalStateException.class)
    public void testStop_WhenNotStarted_ShouldThrowIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        // State is STATE_STOPPED initially (or similar non-running state)
        stopWatch.stop();
    }

    @Test(expected = IllegalStateException.class)
    public void testStop_WhenAlreadyStopped_ShouldThrowIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.stop();

        // Second stop should throw exception as state is now STATE_STOPPED
        stopWatch.stop();
    }

    @Test
    public void testStop_AfterReset_ShouldThrowIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.reset();

        try {
            stopWatch.stop();
            fail("Expected IllegalStateException to be thrown");
        } catch (IllegalStateException e) {
            assertEquals("Stopwatch is not running. ", e.getMessage());
        }
    }
}
